`timescale 1ns/1ps
package reference_pkg;
import uvm_pkg::*;
`include "uvm_macros.svh"
class native_transaction extends uvm_sequence_item;
  `uvm_object_utils(native_transaction)
  logic [37:0] drive;
  logic [36:0] actual, expected;
  bit sample;
  int unsigned tag;
  function new(string name="native_transaction"); super.new(name); endfunction
endclass
class native_sequence extends uvm_sequence #(native_transaction);
  `uvm_object_utils(native_sequence)
  function new(string name="native_sequence"); super.new(name); endfunction
  task send(logic [37:0] drive, bit sample, int unsigned tag);
    native_transaction item = native_transaction::type_id::create("item");
    start_item(item); item.drive=drive; item.sample=sample; item.tag=tag; finish_item(item);
  endtask
  virtual native_if witness_bus;
  task pc3_edge_witnesses();
    logic [31:0] first_data;
    if(!uvm_config_db#(virtual native_if)::get(null,"uvm_test_top.env.sequencer","bus",witness_bus))
      `uvm_fatal("WITNESS_IF","Missing independent reference interface")
    for(int data_bit=0;data_bit<32;data_bit++) begin
      for(int polarity=0;polarity<2;polarity++) begin
        first_data=polarity ? ~(32'b1 << data_bit) : (32'b1 << data_bit);
        send({1'b0,1'b0,1'b0,1'b0,32'b0,1'b0,1'b0},1'b1,256);
        send({1'b0,1'b0,1'b0,1'b0,first_data,1'b1,1'b0},1'b1,7);
        send({1'b0,1'b1,1'b0,1'b0,first_data,1'b1,1'b0},1'b1,7);
        if(witness_bus.exp_usage_o!==3'b0 || witness_bus.exp_empty_o!==1'b0 || witness_bus.exp_data_o!==first_data)
          `uvm_error("RESET_RELEASE_NONVACUITY","Reset release without clock must preserve empty storage and live bypass")
        send({1'b1,1'b1,1'b0,1'b0,first_data,1'b1,1'b0},1'b1,7);
        send({1'b1,1'b1,1'b0,1'b0,~first_data,1'b1,1'b0},1'b1,7);
        if(witness_bus.exp_usage_o!==3'b1 || witness_bus.exp_data_o!==first_data)
          `uvm_error("WRITE_HOLD_NONVACUITY","Stored head must retain edge-sampled data while clock remains high")
        send({1'b0,1'b1,1'b0,1'b0,~first_data,1'b0,1'b0},1'b1,7);
      end
    end
  endtask
  task body();
    int seed=1;
    if (!$value$plusargs("EVENT_SEED=%d", seed))
      void'($value$plusargs("ntb_random_seed=%d", seed));
    send(38'h0,1'b1,256);
    send(38'h1000000000,1'b1,256);
    send(38'h0,1'b1,256);
    send(38'h1000000000,1'b1,256);
